JobService jobService = ServiceLocator.locate(JobService.class);
JobParameters jobParameters = jobService.newJobParameters("example__c");
jobService.runJob(jobParameters);

QueryService queryService = ServiceLocator.locate(QueryService.class); Query query = queryService .newQueryBuilder() .withSelect(asList("id")) .withFrom("documents") .build();
QueryCountRequest queryCountRequest = queryService .newQueryCountRequestBuilder() .withQuery(query) .build();
queryService.count(queryCountRequest) .onSuccess(queryResponse -> {}) .onError(queryOperationError -> {}) .execute();

QueryService queryService = ServiceLocator.locate(QueryService.class); Query query = queryService .newQueryBuilder() .withSelect(asList("id")) .withFrom("documents") .build();
QueryExecutionRequest queryRequest = queryService .newQueryExecutionRequestBuilder() .withQuery(query) .build();
queryService.query(queryRequest) .onSuccess(queryResponse -> {}) .onError(queryOperationError -> {}) .execute();

List<String> versionList = VaultCollections.newList();
versionList.add("1_1_0");
versionList.add("2_1_0");

QueryService queryService = ServiceLocator.locate(QueryService.class);
Query query = queryService
		.newQueryBuilder()
		.withSelect(asList("title__v"))
		.withFrom("documents")
		.withWhere("version_id CONTAINS (${Custom.version_id})")
		.appendWhere(QueryLogicalOperator.AND,
				"version_creation_date__v > ${Custom.my_date}")
		.build();

TokenService tokenService = ServiceLocator.locate(TokenService.class);
TokenRequest tokenRequest = tokenService.newTokenRequestBuilder()
		.withValue("Custom.version_id", versionList)
		.withValue("Custom.my_date", LocalDate.now().minusDays(7))
		.build();

QueryExecutionRequest queryRequest = queryService
		.newQueryExecutionRequestBuilder()
		.withQuery(query)
		.withTokenRequest(tokenRequest)
		.build();

queryService.query(queryRequest)
		.onSuccess(queryResponse -> {
			queryResponse.streamResults().forEach(queryExecutionResult -> {
						String title = queryExecutionResult.getValue("title__v", ValueType.STRING);
					}
			);
		})
		.onError(queryOperationError -> {
			LogService logger = ServiceLocator.locate(LogService.class);
			logger.debug("error!");
		})
		.execute();

QueryService queryService = ServiceLocator.locate(QueryService.class); Query query = queryService .newQueryBuilder() .withSelect(asList("id")) .withFrom("documents") .build();
QueryValidationRequest queryRequest = queryService .newQueryValidationRequestBuilder() .withQuery(query) .build();
queryService.validate(queryRequest) .onSuccess(queryResponse -> {}) .onError(queryOperationError -> {}) .execute();

NotificationService notificationService = ServiceLocator.locate(NotificationService.class);
NotificationParameters notificationParameters = notificationService.newNotificationParameters();
Set<String> recipients = VaultCollections.newSet();
recipients.add(RequestContext.get().getInitiatingUserId());
notificationParameters.setRecipientsByUserIds(recipients);
NotificationTemplate template = notificationService.newNotificationTemplate().setTemplateName("demo__c");
notificationService.send(notificationParameters, template);

